import React, { Component } from 'react';
import './googlemap.css';
import AudioPlayer from 'react-h5-audio-player';
import 'react-h5-audio-player/lib/styles.css';
import moment from 'moment';

class Map extends Component {
    constructor(props) {
        super(props);
        this.state = {
            selectedTime: '',
            petLocations: [],
            playing: false,
            currentPointIndex: 0,
            intervalId: null,
            currentPhoto: null,
            mapLoaded: false,
            currentTimestamp: null,
            baseTime: moment(),
            view: 'location',
            showtrack: false,
        };
        this.map = null;
        this.panorama = null;
    }

    componentDidMount() {
        this.loadScript();
    }

    componentWillUnmount() {
        const script = document.getElementById('googleMaps');
        if (script) {
            document.head.removeChild(script);
        }
        if (this.state.intervalId) {
            clearInterval(this.state.intervalId);
        }
    }

    loadScript = () => {
        const existingScript = document.getElementById('googleMaps');
        if (!existingScript) {
            const script = document.createElement('script');
            script.src = "https://maps.googleapis.com/maps/api/js?key=AIzaSyB5t8KXIpcdx0n3I7FtsVtCJ86YoDngaYw&libraries=places&callback=initMap";
            script.id = 'googleMaps';
            script.async = true;
            script.defer = true;
            window.initMap = this.initMap;
            document.head.appendChild(script);
        } else {
            this.initMap();
        }
    };

    initMap = () => {
        if (window.google && window.google.maps) {
            const fenway = { lat: 32.074572, lng: 34.797105 };
            this.map = new window.google.maps.Map(document.getElementById('map'), {
                zoom: 12,
                center: fenway,
            });

            this.setState({ mapLoaded: true });
            this.fetchData(); // Fetch current pet location on load
        } else {
            console.error("Google Maps API failed to load.");
        }
    };

    fetchData = () => {
        fetch('http://localhost:3001/trackipetmap', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ pet_id: 1 }),
        })
            .then((response) => response.json())
            .then((data) => {
                const { lat, lng } = data;
                this.map.setCenter({ lat, lng });
                new window.google.maps.Marker({
                    position: { lat, lng },
                    map: this.map,
                    title: 'Pet Location',
                });
            })
            .catch((error) => console.error('Error fetching location:', error));
    };

    calculateTimePeriod = (selectedTime) => {
        let baseTime = moment();
        if (selectedTime.includes('last')) {
            const [_, value, unit] = selectedTime.split(' ');
            baseTime = baseTime.subtract(value, unit);
        } else if (selectedTime === 'last day') {
            baseTime = baseTime.subtract(1, 'day');
        } else if (selectedTime === 'last week') {
            baseTime = baseTime.subtract(1, 'week');
        }
        return baseTime;
    };

    handleTimeChange = (event) => {
        const selectedTime = event.target.value;
        const baseTime = this.calculateTimePeriod(selectedTime);
        this.setState({ selectedTime, baseTime });
    };

    showHistory = () => {
        const { selectedTime, baseTime } = this.state;
        if (!selectedTime) {
            alert('Please select a time period.');
            return;
        }

        console.log(`Fetching location history for time: ${selectedTime}`);
        fetch(`http://localhost:3001/locationhistory?pet_id=1&time=${baseTime.toISOString()}`)
            .then((response) => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.json();
            })
            .then((data) => {
                if (data.length === 0) {
                    alert('No location history found for the selected time period.');
                    return;
                }
                console.log(`Fetched location history: ${JSON.stringify(data)}`);
                this.setState({ petLocations: data, currentPointIndex: 0, currentPhoto: null, showtrack: true }, this.playHistory);
                this.initPanorama(); // Initialize panorama when history is shown
            })
            .catch((error) => console.error('Error fetching location history:', error));
    };

    initPanorama = () => {
        const fenway = { lat: 32.074572, lng: 34.797105 };
        this.panorama = new window.google.maps.StreetViewPanorama(
            document.getElementById('pano'),
            {
                position: fenway,
                pov: {
                    heading: 34,
                    pitch: 10,
                },
            }
        );
        this.map.setStreetView(this.panorama);
    };

    playHistory = () => {
        if (!this.state.playing) {
            const intervalId = setInterval(() => {
                const { currentPointIndex, petLocations, baseTime } = this.state;
                if (currentPointIndex >= petLocations.length) {
                    clearInterval(this.state.intervalId);
                    this.setState({ playing: false });
                    return;
                }

                const point = petLocations[currentPointIndex];
                const timestamp = moment(baseTime).add(currentPointIndex, 'hours').toISOString(); // שימוש בזמן הבסיסי

                this.addMarkerAndLine({ ...point, timestamp });

                this.setState({ currentPointIndex: currentPointIndex + 1, currentTimestamp: timestamp });
            }, 1000);

            this.setState({ intervalId, playing: true });
        }
    };

    stopHistory = () => {
        if (this.state.intervalId) {
            clearInterval(this.state.intervalId);
            this.setState({ playing: false, intervalId: null });
        }
    };

    addMarkerAndLine = (point) => {
        const marker = new window.google.maps.Marker({
            position: { lat: parseFloat(point.latitude), lng: parseFloat(point.longitude) },
            map: this.map,
            title: `Pet Location at ${point.timestamp}`,
        });

        if (this.state.currentPointIndex > 0) {
            const previousPoint = this.state.petLocations[this.state.currentPointIndex - 1];
            const line = new window.google.maps.Polyline({
                path: [
                    { lat: parseFloat(previousPoint.latitude), lng: parseFloat(previousPoint.longitude) },
                    { lat: parseFloat(point.latitude), lng: parseFloat(point.longitude) },
                ],
                geodesic: true,
                strokeColor: '#FF0000',
                strokeOpacity: 1.0,
                strokeWeight: 2,
            });
            line.setMap(this.map);
        }

        // Requesting place details from Google Places service
        const service = new window.google.maps.places.PlacesService(this.map);
        const request = {
            location: new window.google.maps.LatLng(point.latitude, point.longitude),
            radius: '50'
        };

        service.nearbySearch(request, (results, status) => {
            if (status === window.google.maps.places.PlacesServiceStatus.OK && results.length > 0) {
                const place = results[0];
                console.log('Nearby search results:', results);
                const photoUrl = place.photos && place.photos.length > 0
                    ? place.photos[0].getUrl({ maxWidth: 100, maxHeight: 100 })
                    : '';

                if (photoUrl) {
                    console.log('Photo URL:', photoUrl);
                } else {
                    console.log('No photo available for this location.');
                }

                this.setState({
                    currentPhoto: {
                        name: place.name,
                        lat: point.latitude,
                        lng: point.longitude,
                        photoUrl: photoUrl
                    }
                });

                // Requesting Street View image
                if (window.google.maps.StreetViewService) {
                    const streetViewService = new window.google.maps.StreetViewService();
                    const STREETVIEW_MAX_DISTANCE = 50;

                    streetViewService.getPanorama({
                        location: new window.google.maps.LatLng(point.latitude, point.longitude),
                        radius: STREETVIEW_MAX_DISTANCE
                    }, this.processStreetViewData);
                } else {
                    console.error('StreetViewService is not available.');
                }
            } else {
                console.error('Nearby search failed or no photos available:', status);
            }
        });
    };

    processStreetViewData = (data, status) => {
        if (status === window.google.maps.StreetViewStatus.OK) {
            this.panorama.setPosition(data.location.latLng);
            this.panorama.setPov({
                heading: 34,
                pitch: 10,
            });
        } else {
            console.error('Street View data not found for this location.');
        }
    };

    setView = (view) => {
        this.setState({ view });
        if (view === 'location') {
            this.fetchData();
        }
    };

    renderSidebar = () => {
        const { view, selectedTime, currentTimestamp } = this.state;

        if (view === 'track') {
            return (
                <div className="sidebar">
                    <button onClick={() => this.setView('location')} className="back-button">&larr;</button>
                    <select onChange={this.handleTimeChange} value={selectedTime}>
                        <option value="">Select Time Period</option>
                        {Array.from({ length: 24 }, (_, i) => (
                            <option key={i + 1} value={`last ${i + 1} hours`}>{`Last ${i + 1} hours`}</option>
                        ))}
                        <option value="last day">Last Day</option>
                        <option value="last week">Last Week</option>
                    </select>
                    <button className='show' onClick={this.showHistory}>Show History</button>
                    {currentTimestamp && (
                        <div className="timestamp-container">
                            <h4>{moment(currentTimestamp).format('YYYY-MM-DD HH:mm:ss')}</h4>
                        </div>
                    )}
                </div>
            );
        }

        return (
            <div className="sidebar">
                <button className="show" onClick={() => this.setView('location')}>Pet Location</button>
                <button className="show" onClick={() => this.setView('track')}>Pet Track</button>
            </div>
        );
    };

    render() {
        const { currentPhoto, mapLoaded, showtrack } = this.state;
        console.log("Current Photo:", currentPhoto);
        console.log("Map Loaded:", mapLoaded);

        return (
            <div className="app-container">
                <div className="content-container-2">
                    {this.renderSidebar()}
                    <div id="map" className="map-container"></div>
                    {showtrack && (
                        <div id="pano" className="map-streetview-container"></div>
                    )}
                    {currentPhoto && currentPhoto.photoUrl && (
                        <div className="map-photo-container">
                            <img src={currentPhoto.photoUrl} alt={currentPhoto.name} className="small-photo" />
                            <h3>{currentPhoto.name}</h3>
                            <p>Latitude: {currentPhoto.lat}</p>
                            <p>Longitude: {currentPhoto.lng}</p>
                        </div>
                    )}
                    {mapLoaded && showtrack && (
                        <div className="audio-player-overlay">
                            <AudioPlayer
                                src="URL_OF_YOUR_AUDIO_FILE"
                                onPlay={this.playHistory}
                                onPause={this.stopHistory}
                                showJumpControls={false}
                                customAdditionalControls={[]}
                            />
                        </div>
                    )}
                </div>
            </div>
        );
    }
}

export default Map;
